<script setup>
import { nextTick, ref } from 'vue'
const dialog=ref(false),draft=ref(''),files=ref([]),thread=ref(null),messages=ref([]),preview=ref('')
const capabilities=[
  {icon:'dashboard_customize',title:'Templates a partir de prints',text:'Interpreta idioma, categoria, variáveis e botões; prepara clones e sites para revisão.',prompt:'Como você cria e clona templates a partir dos prints oficiais da Meta?'},
  {icon:'account_tree',title:'Fluxogramas completos',text:'Desenha jornadas, decisões, IA e transferência para a equipe; gera JSON compatível.',prompt:'Como você cria um fluxograma completo e sugere melhorias para o atendimento?'},
  {icon:'campaign',title:'Campanhas e e-mails',text:'Ajuda a selecionar contatos, grupos, canal e conteúdo antes da confirmação do envio.',prompt:'Como você prepara campanhas, notificações e emails em HTML?'},
  {icon:'settings_suggest',title:'Configurar os canais',text:'Explica campos, orienta as integrações e prepara alterações nas áreas autorizadas.',prompt:'Como você ajuda a configurar canais, tokens e segurança?'},
  {icon:'manage_search',title:'Consultar e organizar',text:'Consulta registros, contatos e histórico conforme as permissões do perfil.',prompt:'Como você consulta contatos, histórico, logs e permissões?'},
  {icon:'mic',title:'Texto, áudio e arquivos',text:'No app real, usa áudio, prints e documentos para entender pedidos e gerar conteúdos.',prompt:'Como funcionam áudio, imagens, documentos, geração de arquivos e o consumo de tokens?'},
]
function open(){dialog.value=true}
defineExpose({open})
function answer(){
  if(!draft.value.trim()&&!files.value.length)return
  const text=draft.value.trim()||'Analise estes prints',names=files.value.map(file=>file.name)
  messages.value.push({role:'user',text,names})
  const lower=text.toLowerCase()
  preview.value=''
  let response='Sou o Aito I.A, agente integrado à plataforma. No aplicativo real posso ajudar a criar templates e sites, gerar fluxogramas em JSON, preparar campanhas e e-mails, consultar contatos e histórico, orientar integrações e configurar canais. Você revisa as ações antes da execução; as permissões do perfil e as limitações de cada canal continuam valendo. Nesta demonstração, minhas respostas são exemplos e não consomem créditos.'
  if(/template|print|modelo|clon/.test(lower)||names.length){response='Eu leria os prints e preservaria o nome oficial, idioma, categoria e ordem das variáveis. Se uma URL estiver cortada ou faltar informação, perguntaria antes de preparar o cadastro. Para clonar, criaria um novo registro sem alterar o original. Veja abaixo um exemplo fictício de revisão.';preview.value='template'}
  else if(/email|e-mail|campanha|disparo|notifica/.test(lower)){response='Primeiro eu confirmaria o canal, o público, o template e as variáveis. Antes do envio, verificaria as permissões e as limitações do canal. Depois mostraria destinatários e conteúdo para sua confirmação. Aqui não há envio nem consulta de contatos reais.';preview.value='campaign'}
  else if(/flux|bot/.test(lower)){response='Podemos desenhar boas-vindas → escolha → resposta com IA ou triagem humana. No app real eu gero um JSON compatível, valido conexões e preparo a importação para revisão. Nesta demonstração, abra Fluxos e simulador para conhecer os cards.';preview.value='flow'}
  else if(/configur|chave|canal|seguran|api token/.test(lower)){response='No app real eu explico cada campo e preparo alterações com confirmação. A chave da OpenAI fica protegida no servidor; colaboradores só usam as áreas liberadas. Nunca informe uma chave, senha ou dado pessoal nesta demonstração.';preview.value='settings'}
  else if(/consult|histor|log|permiss|contato/.test(lower)){response='No aplicativo real posso consultar contatos, grupos, templates, notificações e registros operacionais nas áreas autorizadas. Se houver pessoas com nomes parecidos, peço que você confirme o contato pelo nome, telefone ou e-mail antes de preparar uma ação. Alterações e remoções exigem revisão, e limpezas sensíveis têm confirmação reforçada. Aqui não leio dados reais.'}
  else if(/audio|áudio|voz|document|arquivo|imagem|consumo/.test(lower)){response='No aplicativo real, você pode escrever, gravar áudio para transcrição, colar prints e anexar vários arquivos. Conforme o modelo e a configuração, o agente interpreta o conteúdo e pode gerar imagens ou documentos. A configuração da OpenAI permanece salva; o contexto pode ser limpo separadamente. O painel apresenta logs, tokens e estimativas de custo quando há preços configurados. Na demonstração, não transcrevo, não envio anexos e não gasto tokens.'}
  messages.value.push({role:'assistant',text:response});draft.value='';files.value=[]
  nextTick(()=>thread.value?.scrollTo({top:thread.value.scrollHeight,behavior:'smooth'}))
}
function shortcut(value){draft.value=value}
function explainCapability(value){draft.value=value;answer()}
</script>
<template>
  <button class="demo-ai-float" aria-label="Conhecer Aito I.A na demonstração" @click="open"><img src="/comunicacao/app/ia.gif" alt=""/><q-tooltip>Aito I.A · demonstração fictícia</q-tooltip></button>
  <q-dialog v-model="dialog" persistent :maximized="$q.screen.lt.md"><q-card class="demo-ai-dialog"><header><img src="/comunicacao/app/ia.gif" alt=""/><div><strong>Aito I.A</strong><small>Agente fictício · não usa token ou créditos</small></div><q-space/><q-btn flat round dense icon="refresh" aria-label="Limpar conversa fictícia" @click="messages=[];preview=''"/><q-btn flat round dense icon="close" aria-label="Fechar agente demonstrativo" @click="dialog=false"/></header>
    <q-banner class="demo-ai-notice">Respostas de exemplo. Nenhuma ação é executada e nenhum arquivo é enviado.</q-banner>
    <div ref="thread" class="demo-ai-thread"><section v-if="!messages.length" class="demo-ai-welcome"><q-icon name="auto_awesome"/><h2>Seu agente dentro da operação.</h2><p>Conheça as principais funcionalidades do Aito I.A. No aplicativo real ele usa a credencial OpenAI configurada e executa ações autorizadas após a revisão.</p><div class="demo-ai-capabilities"><button v-for="item in capabilities" :key="item.title" @click="explainCapability(item.prompt)"><q-icon :name="item.icon"/><strong>{{item.title}}</strong><span>{{item.text}}</span><small>Ver exemplo <q-icon name="arrow_forward"/></small></button></div></section><article v-for="(message,index) in messages" :key="index" :class="['demo-ai-message',message.role]"><small>{{message.role==='user'?'Você':'Aito I.A · exemplo'}}</small><p>{{message.text}}</p><span v-for="name in message.names||[]" :key="name" class="demo-ai-file"><q-icon name="attach_file"/> {{name}}</span></article>
      <section v-if="preview" class="demo-ai-preview"><q-badge outline color="primary">REVISÃO ILUSTRATIVA</q-badge><h3>{{({template:'Cadastrar template de confirmação',campaign:'Preparar campanha por grupo',flow:'Criar fluxo de atendimento',settings:'Configurar canal com segurança'})[preview]}}</h3><template v-if="preview==='template'"><p v-pre>Nome: appointment_reminder · pt_BR · Utilidade<br/>Cabeçalho: Seu agendamento<br/>Corpo: Olá {{1}}, seu atendimento será em {{2}}.<br/>Variáveis: nome e data, ambas dinâmicas.</p></template><p v-else-if="preview==='campaign'">Canal: WhatsApp Cloud · Grupo: Clientes<br/>Template: Lembrete de agendamento<br/>Público fictício: 120 contatos · sem envio real.</p><p v-else>Dados e ações seriam apresentados em um cartão de revisão, respeitando as permissões e validações da plataforma.</p><q-btn outline no-caps color="primary" label="Execução indisponível no protótipo" disable/></section>
    </div><section class="demo-ai-composer"><div class="demo-ai-shortcuts"><q-btn flat dense no-caps label="Cadastrar por print" @click="shortcut('Como você cadastra um template a partir de prints oficiais?')"/><q-btn flat dense no-caps label="Criar fluxograma" @click="shortcut('Como você cria um fluxograma completo?')"/><q-btn flat dense no-caps label="Preparar campanha" @click="shortcut('Como você prepara uma campanha para grupos?')"/></div><q-input v-model="draft" outlined autogrow type="textarea" maxlength="1500" label="Pergunte sobre o agente (simulação)" @keydown.ctrl.enter.prevent="answer"/><div class="demo-ai-bottom"><q-file v-model="files" multiple outlined dense label="Ver anexos localmente" accept="image/*,.pdf,.txt" :max-files="8"/><q-btn round color="primary" icon="arrow_upward" aria-label="Ver resposta simulada" :disable="!draft.trim()&&!files.length" @click="answer"/></div><small>Não informe dados pessoais ou credenciais. Anexos ficam apenas neste dispositivo durante a simulação.</small></section>
  </q-card></q-dialog>
</template>
<style scoped>
