play:flex;gap:4px;flex-wrap:wrap;margin-bottom:8px}.demo-ai-shortcuts .q-btn{font-size:10px}.demo-ai-composer>small{display:block;font-size:9px;line-height:1.6;color:#6f8376;margin-top:9px}.demo-ai-bottom{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:8px}.demo-ai-bottom>.q-field{max-width:340px;flex:1}@media(max-width:1023px){.demo-ai-dialog{max-width:100vw;width:100vw;height:100dvh;max-height:100dvh;border-radius:0}.demo-ai-dialog>header{padding:9px 13px}.demo-ai-welcome h2{font-size:25px}.demo-ai-composer{padding:8px 13px 12px}.demo-ai-thread{padding:18px}.demo-ai-float{right:12px;bottom:18px;width:56px;height:56px}.demo-ai-float>img{width:43px;height:43px}}
</style>

<style scoped>.demo-ai-welcome{max-width:760px;margin:10px auto 25px}.demo-ai-capabilities{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;text-align:left;margin-top:24px}.demo-ai-capabilities button{display:flex;flex-direction:column;align-items:flex-start;gap:8px;padding:18px;background:white;border:1px solid #d5e8df;border-radius:16px;color:#244b3e;cursor:pointer;text-align:left}.demo-ai-capabilities button:hover{background:#eefbf5;border-color:#76bfa5}.demo-ai-capabilities button>.q-icon{font-size:25px;color:#0a8c6d}.demo-ai-capabilities strong{font-size:13px}.demo-ai-capabilities span{font-size:11px;line-height:1.7;color:#687f73}.demo-ai-capabilities small{font-size:10px;color:#0c886a;margin-top:auto}@media(max-width:550px){.demo-ai-capabilities{grid-template-columns:1fr}.demo-ai-welcome h2{font-size:24px}.demo-ai-capabilities button{padding:14px}}
</style>
